prefix='\n#include <stdint.h>\n#include <limits.h>\n#include <stdio.h>\n#include <string.h>\n#include <errno.h>\n#include <assert.h>\n#define ENOPOLICY 103\n#define CS_VALID 1U\n#define CS_SIGNED 0x20000000U\n#define CS_PLATFORM_BINARY 0x04000000U\n#define PROC_NULL NULL\n#define user_addr_t uintptr_t\ntypedef int pid_t;\nstruct Proc{int pid,uid,parent,bits,platform;unsigned version;uint64_t flags;unsigned char hash[20];};typedef struct Proc*proc_t;\nstatic struct Proc root={.pid=1,.uid=0,.bits=1},app;static proc_t initproc=&root;\nstatic unsigned refs,fault,race;\nstatic int proc_pid(proc_t p){return p->pid;}static int proc_getuid(proc_t p){return p->uid;}\nstatic int proc_ppid(proc_t p){return p->parent;}static int proc_is64bit_data(proc_t p){return p->bits;}\nstatic unsigned proc_pidversion(proc_t p){return p->version;}static uint64_t proc_getcsflags(proc_t p){return p->flags;}\nstatic int csproc_get_platform_binary(proc_t p){return p->platform;}\nstatic proc_t proc_find(pid_t pid){if(pid!=6)return NULL;refs++;return &app;}\nstatic void proc_rele(proc_t p){assert(p==&app&&refs==1);refs--;}\nstatic int proc_getcdhash(proc_t p,unsigned char*out){if(fault==4)return EIO;memcpy(out,p->hash,20);if(race==1)p->version++;if(race==2)p->uid=0;if(race==3)p->platform=0;if(race==4)p->flags=0;if(race==5)p->bits=0;if(race==6)p->parent=7;return 0;}\nstatic int copyin(user_addr_t p,void*out,size_t n){if(!p||fault==1)return EFAULT;memcpy(out,(void*)p,n);return 0;}\nstatic int copyout(const void*p,user_addr_t out,size_t n){if(!out||fault==3)return EFAULT;memcpy((void*)out,p,n);return 0;}\nstatic int copyinstr(user_addr_t p,char*out,size_t max,size_t*n){if(!p||fault==2)return EFAULT;size_t size=strlen((char*)p)+1;if(size>max)return ENAMETOOLONG;memcpy(out,(void*)p,size);*n=size;return 0;}\n'
test='\nstruct Args{uint64_t result,pid,operation,filter_type,filter,flags,pidversion;};\nstatic const unsigned char pins[2][20]={\n{0x45,0x3a,0xe2,0xe6,0x05,0x7a,0xcb,0x2d,0xea,0x0c,0x5a,0xe8,0xba,0x09,0x73,0x07,0x7e,0xa3,0xea,0xb1},\n{0x95,0xf7,0xee,0xff,0x86,0xd8,0xda,0xd6,0x15,0xc7,0xb5,0x78,0xda,0xe5,0x3f,0x61,0x54,0x35,0x1c,0x8d}};\nstatic const char *services[]={"com.apple.backboard.system-app-server","com.apple.CARenderServer","com.apple.backboard.display.services"};\nstatic unsigned which;static uint64_t decision;static struct Args a;\nstatic void reset(void){assert(!refs);fault=race=0;app=(struct Proc){.pid=6,.uid=501,.parent=1,.bits=1,.platform=1,.version=17,.flags=CS_VALID|CS_SIGNED};memcpy(app.hash,pins[which==2],20);decision=99;a=(struct Args){(uintptr_t)&decision,6,(uintptr_t)"mach-lookup",6,(uintptr_t)services[which],0x40000000ULL,17};}\nstatic void rejected(int expected){assert(xcover5_ui_lookup(&root,(uintptr_t)&a)==expected);assert(!refs&&decision==99);}\nint main(void){\n for(which=0;which<3;which++){\n reset();assert(!xcover5_ui_lookup(&root,(uintptr_t)&a)&&decision==0&&!refs);\n reset();memcpy(app.hash,pins[which!=2],20);rejected(ENOPOLICY);\n for(unsigned bit=0;bit<160;bit++){reset();app.hash[bit/8]^=1U<<(bit%8);rejected(ENOPOLICY);}\n reset();app.uid=0;rejected(ENOPOLICY);reset();app.parent=7;rejected(ENOPOLICY);\n reset();app.platform=0;rejected(ENOPOLICY);reset();app.bits=0;rejected(ENOPOLICY);reset();app.version++;rejected(ENOPOLICY);\n for(unsigned v=1;v<=6;v++){reset();race=v;rejected(ENOPOLICY);}\n reset();app.flags=CS_VALID;rejected(ENOPOLICY);reset();app.flags=CS_SIGNED;rejected(ENOPOLICY);\n reset();a.operation=(uintptr_t)"mach-cross-domain-lookup";rejected(ENOPOLICY);\n reset();a.filter_type=7;rejected(ENOPOLICY);reset();a.flags=1;rejected(ENOPOLICY);\n reset();a.flags=0x40000001ULL;rejected(ENOPOLICY);\n reset();a.pidversion=0;rejected(ENOPOLICY);reset();a.pidversion=UINT64_MAX;rejected(ENOPOLICY);\n reset();a.pid=0;rejected(ENOPOLICY);reset();a.pid=7;rejected(ESRCH);reset();a.pid=(uint64_t)INT_MAX+1;rejected(ENOPOLICY);\n for(unsigned f=1;f<=4;f++){reset();fault=f;rejected(f==4?ENOPOLICY:EFAULT);}\n reset();struct Proc imposter=root;assert(xcover5_ui_lookup(&imposter,(uintptr_t)&a)==ENOPOLICY&&decision==99);\n reset();root.uid=501;rejected(ENOPOLICY);root.uid=0;\n reset();root.bits=0;rejected(ENOPOLICY);root.bits=1;\n reset();a.filter=(uintptr_t)"com.apple.CARenderServer.fake";rejected(ENOPOLICY);\n reset();a.filter=(uintptr_t)"com.apple.logd";rejected(ENOPOLICY);\n }\n return 0;\n}\n'
